#include <iomanip>
#include <iostream>
#include "mesh/cubed_sphere/centered_surface_atlas.hpp"
namespace c=cubed_sphere;
c::Jet Exact(const Real*x){c::Jet X=c::Jet::Variable(x[0],0),Y=c::Jet::Variable(x[1],1),Z=c::Jet::Variable(x[2],2),R=c::Power(X*X+Y*Y+Z*Z,.5);X=X/R;Y=Y/R;Z=Z/R;return c::Jet(1)+c::Jet(.2)*X+c::Jet(.3)*X*Y+c::Jet(.4)*Y*Z+c::Jet(.1)*X*X*X;}
struct Norm {Real first=0,second=0,value=0;int count=0;void Add(const c::CenteredSurfaceAtlas::Jets&u,const c::Jet&e){++count;value=std::max(value,std::abs(u.value[1]-e.f));for(int i=0;i<3;++i){first=std::max(first,std::abs(u.d[1][i]-e.d[i]));for(int j=0;j<3;++j)second=std::max(second,std::abs(u.dd[1][i][j]-e.h[i][j]));}}void Print()const{std::cout<<"{\"count\":"<<count<<",\"value_max\":"<<value<<",\"first_max\":"<<first<<",\"second_max\":"<<second<<'}';}};
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int result=0;try{std::cout<<std::setprecision(17);Real prior1=0,prior2=0;for(int n:{6,12,24}){c::CompositeMesh mesh(.25,{.65,1},1,n,2);c::CenteredSurfaceAtlas atlas(mesh,2);for(size_t b=0;b<mesh.blocks.size();++b)if(atlas.base[b]>=0)for(int k=0;k<n;++k)for(int j=0;j<n;++j){Real q[3]={1,(j+.5)/n,(k+.5)/n},x[3];mesh.Forward(b,q,x);int p=atlas.base[b]+j+n*k;atlas.values[2*p]=3.14159;atlas.values[2*p+1]=Exact(x).f;}
 Norm bulk,edge,corner,seam;Real constant=0;for(size_t b=0;b<mesh.blocks.size();++b)if(atlas.base[b]>=0){auto probe=[&](Real u,Real v,Norm&norm){Real q[3]={1,u,v};const auto geometry=mesh.Geometry(b,q);const auto a=atlas.At(b,q);norm.Add(a,Exact(geometry.x));constant=std::max(constant,std::abs(a.value[0]-3.14159));for(int i=0;i<3;++i){constant=std::max(constant,std::abs(a.d[0][i]));for(int j=0;j<3;++j)constant=std::max(constant,std::abs(a.dd[0][i][j]));}};
 for(int k=0;k<n;++k)for(int j=0;j<n;++j){const bool e=(j<2||j>=n-2),f=(k<2||k>=n-2);probe((j+.5)/n,(k+.5)/n,e&&f?corner:(e||f?edge:bulk));}for(int j=0;j<=n;++j){probe(0,Real(j)/n,seam);probe(1,Real(j)/n,seam);probe(Real(j)/n,0,seam);probe(Real(j)/n,1,seam);}}
 const Real first=std::max({bulk.first,edge.first,corner.first,seam.first}),second=std::max({bulk.second,edge.second,corner.second,seam.second});std::cout<<"{\"n\":"<<n<<",\"constant_max\":"<<constant<<",\"first_ratio\":"<<(prior1?prior1/first:0)<<",\"second_ratio\":"<<(prior2?prior2/second:0)<<",\"bulk\":";bulk.Print();std::cout<<",\"edge_band\":";edge.Print();std::cout<<",\"corner_band\":";corner.Print();std::cout<<",\"exact_seams_and_corners\":";seam.Print();std::cout<<"}\n";if(constant>1e-14||!std::isfinite(first+second)|| (prior1&&first>=prior1)|| (prior2&&second>=prior2))throw std::runtime_error("atlas consistency/convergence failed");prior1=first;prior2=second;}
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';result=2;}Kokkos::finalize();return result;}
